mapper.select:
SELECT COUNT(*) FROM version_release r
WHERE r.workspace_id = #{workspaceId} AND 
  AND r.occurred_at >= #{from} AND r.occurred_at < #{before}
AND r.req_id = #{reqId}

SELECT r.status AS `key`, COUNT(*) AS count
FROM test_case_run r
JOIN test_case c ON c.id = r.case_id AND c.workspace_id = r.workspace_id
WHERE r.workspace_id = #{workspaceId}
  AND r.created_at >= #{from} AND r.created_at < #{before}
AND c.req_id = #{reqId}
GROUP BY r.status

SELECT COUNT(*) FROM test_case c
WHERE c.workspace_id = #{workspaceId}
  AND c.created_at >= #{from} AND c.created_at < #{before}
AND c.req_id = #{reqId}

SELECT COUNT(*) FROM test_case c
WHERE c.workspace_id = #{workspaceId} AND c.latest_status = 'failed'
AND c.req_id = #{reqId}

SELECT COUNT(*) FROM requirement_doc d
WHERE d.workspace_id = #{workspaceId}
  AND d.created_at >= #{from} AND d.created_at < #{before}

SELECT COUNT(*) FROM requirement_doc_history h
JOIN requirement_doc d ON d.id = h.doc_id AND d.workspace_id = h.workspace_id
WHERE h.workspace_id = #{workspaceId}
  AND h.created_at >= #{from} AND h.created_at < #{before}

SELECT COUNT(*) FROM requirement_doc d
WHERE d.workspace_id = #{workspaceId}
  AND d.published_at >= #{from} AND d.published_at < #{before}

SELECT COUNT(*) FROM requirement_doc d
WHERE d.workspace_id = #{workspaceId} AND d.status = 'draft'
  AND d.updated_at < #{before}

SELECT MIN(d.updated_at) FROM requirement_doc d
WHERE d.workspace_id = #{workspaceId} AND d.status = 'draft'
  AND d.updated_at < #{before}

SELECT x.`key`, SUM(x.cnt) AS count FROM (
  SELECT d.doc_type AS `key`, COUNT(*) AS cnt
  FROM requirement_doc d
  WHERE d.workspace_id = #{workspaceId}
    AND d.created_at >= #{from} AND d.created_at < #{before}

  GROUP BY d.doc_type
  UNION ALL
  SELECT d.doc_type AS `key`, COUNT(*) AS cnt
  FROM requirement_doc_history h
  JOIN requirement_doc d ON d.id = h.doc_id AND d.workspace_id = h.workspace_id
  WHERE h.workspace_id = #{workspaceId}
    AND h.created_at >= #{from} AND h.created_at < #{before}

  GROUP BY d.doc_type
) x
GROUP BY x.`key`
ORDER BY count DESC

SELECT COALESCE(SUM(l.minutes), 0)
FROM time_log l
JOIN task t ON t.id = l.task_id AND t.workspace_id = l.workspace_id
WHERE l.workspace_id = #{workspaceId}
  AND l.started_at >= #{from} AND l.started_at < #{before}
  AND t.deleted_at IS NULL

SELECT t.id, 'task' AS kind, t.item_type AS type, t.title, r.name AS projectName, t.owner AS person, CAST(t.due_date AS DATETIME) AS at,
CONCAT('延期 ', DATEDIFF(DATE(t.completed_at), t.due_date), ' 天完成') CONCAT('截止日在本周 · ', CASE t.board_column WHEN 'backlog' THEN '待处理' WHEN 'doing' THEN '进行中' WHEN 'test' THEN '待测试' WHEN 'testing' THEN '测试中' ELSE t.board_column END) CONCAT('按期完成', CASE WHEN DATE(t.completed_at) < t.due_date THEN CONCAT(' · 提前 ', DATEDIFF(t.due_date, DATE(t.completed_at)), ' 天') ELSE '' END) AS extra FROM task t LEFT JOIN requirement r ON r.id = t.req_id AND r.workspace_id = t.workspace_id WHERE t.workspace_id = #{workspaceId} AND t.deleted_at IS NULL AND t.canceled_at IS NULL AND t.due_date >= #{from} AND t.due_date <= #{to}
AND t.completed_at IS NOT NULL AND DATE(t.completed_at) > t.due_date AND t.completed_at IS NULL AND t.completed_at IS NOT NULL AND DATE(t.completed_at) <= t.due_date
ORDER BY t.due_date, t.priority, BINARY t.id LIMIT #{limit}

SELECT COUNT(*) FROM project_milestone m
WHERE m.workspace_id = #{workspaceId}
  AND m.canceled_at IS NULL AND m.achieved_at IS NULL
  AND m.target_date >= #{from} AND m.target_date <= #{to}
AND m.req_id = #{reqId}

SELECT COUNT(*) FROM version_release_plan p
WHERE p.workspace_id = #{workspaceId}
  AND p.status = 'ready' AND p.planned_at IS NOT NULL AND p.planned_at < #{now}
AND EXISTS (
  SELECT 1 FROM version_release_plan_version pv
  WHERE pv.workspace_id = p.workspace_id AND pv.plan_id = p.id AND pv.req_id = #{reqId})

SELECT COUNT(*) FROM test_plan p
WHERE p.workspace_id = #{workspaceId}
  AND p.status = 'running' AND p.planned_end IS NOT NULL AND p.planned_end < #{today}
AND p.req_id = #{reqId}

SELECT p.id, p.name, p.status, DATE_FORMAT(p.planned_end, '%Y-%m-%d') AS plannedEnd,
       COUNT(c.case_id) AS total,
       COALESCE(SUM(CASE WHEN c.result = 'passed' THEN 1 ELSE 0 END), 0) AS passed
FROM test_plan p
LEFT JOIN test_plan_case c ON c.plan_id = p.id
WHERE p.workspace_id = #{workspaceId}
  AND p.planned_end IS NOT NULL AND p.planned_end >= #{from} AND p.planned_end <= #{to}
AND p.req_id = #{reqId}
GROUP BY p.id, p.name, p.status, p.planned_end
ORDER BY p.planned_end DESC

SELECT COUNT(*) FROM version_release r
WHERE r.workspace_id = #{workspaceId} AND r.result = 'success'
  AND r.environment = 'production' AND r.operation = 'rollback'
  AND r.occurred_at >= #{from} AND r.occurred_at < #{before}
AND r.req_id = #{reqId}

SELECT p.status AS `key`, COUNT(*) AS count
FROM test_plan p
WHERE p.workspace_id = #{workspaceId}
  AND p.planned_end IS NOT NULL AND p.planned_end >= #{from} AND p.planned_end <= #{to}
AND p.req_id = #{reqId}
GROUP BY p.status

SELECT COUNT(DISTINCT r.executed_by_user_id)
FROM test_case_run r
JOIN test_case c ON c.id = r.case_id AND c.workspace_id = r.workspace_id
WHERE r.workspace_id = #{workspaceId}
  AND r.created_at >= #{from} AND r.created_at < #{before}
  AND r.executed_by_user_id IS NOT NULL
AND c.req_id = #{reqId}

SELECT d.owner_user_id AS userId, COUNT(*) AS count
FROM requirement_doc d
WHERE d.workspace_id = #{workspaceId}
  AND d.created_at >= #{from} AND d.created_at < #{before}
  AND d.owner_user_id IS NOT NULL

GROUP BY d.owner_user_id

SELECT r.executed_by_user_id AS userId, COUNT(*) AS count
FROM test_case_run r
JOIN test_case c ON c.id = r.case_id AND c.workspace_id = r.workspace_id
WHERE r.workspace_id = #{workspaceId}
  AND r.created_at >= #{from} AND r.created_at < #{before}
  AND r.executed_by_user_id IS NOT NULL
AND c.req_id = #{reqId}
GROUP BY r.executed_by_user_id

SELECT c.created_by_user_id AS userId, COUNT(*) AS count
FROM test_case c
WHERE c.workspace_id = #{workspaceId}
  AND c.created_at >= #{from} AND c.created_at < #{before}
  AND c.created_by_user_id IS NOT NULL
AND c.req_id = #{reqId}
GROUP BY c.created_by_user_id

SELECT c.user_id AS userId, COUNT(*) AS count
FROM demand_comment c
JOIN demand d ON d.id = c.demand_id AND d.workspace_id = c.workspace_id
WHERE c.workspace_id = #{workspaceId}
  AND c.created_at >= #{from} AND c.created_at < #{before}

GROUP BY c.user_id

SELECT r.executor_user_id AS userId, COUNT(*) AS count
FROM version_release r
WHERE r.workspace_id = #{workspaceId}
  AND r.occurred_at >= #{from} AND r.occurred_at < #{before}
AND r.req_id = #{reqId}
GROUP BY r.executor_user_id

SELECT d.req_id AS projectId, r.name AS projectName, COUNT(*) AS count
FROM demand d
LEFT JOIN requirement r ON r.id = d.req_id AND r.workspace_id = d.workspace_id
WHERE d.workspace_id = #{workspaceId}
  AND d.created_at >= #{from} AND d.created_at < #{before}
GROUP BY d.req_id, r.name

SELECT c.id, 'case' AS kind, 'case' AS type, c.title,
       r.name AS projectName, COALESCE(c.created_by, '未记录') AS person,
       c.created_at AS at, COALESCE(c.module, '') AS extra
FROM test_case c
LEFT JOIN requirement r ON r.id = c.req_id AND r.workspace_id = c.workspace_id
WHERE c.workspace_id = #{workspaceId}
  AND c.created_at >= #{from} AND c.created_at < #{before}
AND c.req_id = #{reqId}
ORDER BY c.created_at DESC, BINARY c.id
LIMIT #{limit}

SELECT c.id, 'case' AS kind, r.status AS type, c.title,
       p.name AS projectName, COALESCE(r.executed_by, '未记录') AS person,
       r.created_at AS at, COALESCE(r.note, '') AS extra
FROM test_case_run r
JOIN test_case c ON c.id = r.case_id AND c.workspace_id = r.workspace_id
LEFT JOIN requirement p ON p.id = c.req_id AND p.workspace_id = c.workspace_id
WHERE r.workspace_id = #{workspaceId} AND r.status = #{status}
  AND r.created_at >= #{from} AND r.created_at < #{before}
AND c.req_id = #{reqId}
ORDER BY r.created_at DESC
LIMIT #{limit}

SELECT d.id, 'doc' AS kind, d.doc_type AS type, d.title,
       r.name AS projectName, COALESCE(d.owner, '未记录') AS person,
       d.created_at AS at, d.status AS extra
FROM requirement_doc d
LEFT JOIN requirement r ON r.id = d.req_id AND r.workspace_id = d.workspace_id
WHERE d.workspace_id = #{workspaceId}
  AND d.created_at >= #{from} AND d.created_at < #{before}

ORDER BY d.created_at DESC, BINARY d.id
LIMIT #{limit}

SELECT d.id, 'doc' AS kind, d.doc_type AS type, d.title,
       r.name AS projectName, COALESCE(h.saved_by, '未记录') AS person,
       h.created_at AS at, CONCAT('v', h.version_no) AS extra
FROM requirement_doc_history h
JOIN requirement_doc d ON d.id = h.doc_id AND d.workspace_id = h.workspace_id
LEFT JOIN requirement r ON r.id = d.req_id AND r.workspace_id = d.workspace_id
WHERE h.workspace_id = #{workspaceId}
  AND h.created_at >= #{from} AND h.created_at < #{before}

ORDER BY h.created_at DESC, h.id DESC
LIMIT #{limit}

SELECT d.id, 'doc' AS kind, d.doc_type AS type, d.title,
       r.name AS projectName, COALESCE(d.owner, '未记录') AS person,
       d.published_at AS at, d.status AS extra
FROM requirement_doc d
LEFT JOIN requirement r ON r.id = d.req_id AND r.workspace_id = d.workspace_id
WHERE d.workspace_id = #{workspaceId}
  AND d.published_at >= #{from} AND d.published_at < #{before}

ORDER BY d.published_at DESC, BINARY d.id
LIMIT #{limit}
